// Build one Telegram message from all flagged entries.
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $input.all().map((i) => i.json).filter((r) => r.id != null);
if (rows.length === 0) return []; // no spam today, send nothing

const lines = rows.map((r) => {
  const msg = String(r.message ?? '');
  const short = msg.length > 120 ? msg.slice(0, 120) + '...' : msg;
  return `<b>#${r.id}</b> ${esc(r.name)} (${esc(r.email)})\n${esc(short)}`;
});

let text = `🗂 <b>Spam review: ${rows.length} flagged in the last 24h</b>\n\n` + lines.join('\n\n');
text += `\n\n<i>Restore a real lead: update crm.leads set status = 'new' where id = &lt;id&gt;;</i>`;
if (text.length > 4000) text = text.slice(0, 3990) + '\n...';

return [{ json: { text, count: rows.length } }];

// Leads from the website (signup Worker): demo signups and quote requests. Brevo already has them and keeps sending
// the emails; this keeps every lead in crm.leads too, so the reports see all leads in one place.
const b = $json.body ?? {};
const clean = (v, max) => String(v ?? '').trim().replace(/\s+/g, ' ').slice(0, max);
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const kind = b.kind === 'quote' || b.kind === 'demo' ? b.kind : null;
const email = clean(b.email, 200).toLowerCase();
const name = clean(b.name, 100);
if (!kind || !name || !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) {
  throw new Error(`Invalid website lead (kind: ${String(b.kind).slice(0, 20)}, name: ${!!name}, email: ${!!email})`);
}
const from = clean(b.utm_source, 50).toLowerCase().replace(/[^a-z0-9_-]/g, '') || 'direct';
const phone = clean(b.phone, 40) || null;
const company = clean(b.company, 100) || null;
const demo = clean(b.demo, 60) || 'not specified';
const business = clean(b.business, 100) || 'not specified';
const message = kind === 'quote'
  ? String(b.message ?? '').trim().slice(0, 4000) || '(no answers)'
  : `Demo signup: ${demo}${b.returning ? ' (already confirmed, demo email sent again)' : ' (confirmation email sent)'}`;

// For Telegram, drop the answer lines the header already shows (the full text is still saved).
const answers = message
  .split('\n')
  .filter((l) => !/^(Name|Email|Company|Phone|Business|Came from):/.test(l))
  .join('\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// "#ID" is replaced with the new row's id in the Telegram node.
const text = kind === 'quote'
  ? `💼 <b>New quote request #ID</b>\n\n<b>Name:</b> ${esc(name)}\n<b>Email:</b> ${esc(email)}\n<b>Phone:</b> ${esc(phone ?? '-')}\n<b>Company:</b> ${esc(company ?? '-')}\n<b>Business:</b> ${esc(business)}\n<b>Came from:</b> ${esc(from)}\n\n${esc(answers.length > 900 ? answers.slice(0, 900) + '...' : answers)}\n\n<i>They were told you'd reply within 1 to 2 working days.</i>`
  : `🎟 <b>Demo signup #ID</b>: ${esc(name)}${company ? ` (${esc(company)})` : ''} wants <b>${esc(demo)}</b> · from ${esc(from)}${b.returning ? ' · returning' : ''}`;

return [{
  json: {
    name, email, phone, company, message,
    // quote requests need a reply; demo signups are answered by Brevo's demo emails
    status: kind === 'quote' ? 'new' : 'contacted',
    source: `${kind === 'quote' ? 'quote' : 'demo-signup'}:${from}`,
    silent: kind !== 'quote',
    text,
  },
}];

